package bookstore

import "sort"

// discounts maps a group size to the total price of that group, in cents.
// A single copy of any book costs 800 cents ($8.00). Index 0 is unused.
var discounts = []int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the minimum total price, in cents, for the given basket of
// books. Each book is identified by an integer from 1 to 5.
func Cost(books []int) int {
	counts := make([]int, 5)
	for _, book := range books {
		counts[book-1]++
	}

	cost := 0
	for {
		// Keep the per-title counts sorted in descending order so that the most
		// plentiful titles always come first.
		sort.Sort(sort.Reverse(sort.IntSlice(counts)))

		// n is the number of distinct titles that still have copies left.
		n := 0
		for _, c := range counts {
			if c > 0 {
				n++
			}
		}
		if n == 0 {
			break
		}

		// Form a group from the n most plentiful titles. The only non-trivial
		// decision is whether to form a group of five or a group of four when
		// all five titles are available: two groups of four (2560 + 2560 = 5120)
		// are cheaper than a group of five plus a group of three
		// (3000 + 2160 = 5160). We prefer a group of four whenever the
		// third-most plentiful title has strictly more copies than the
		// fourth-most plentiful one, since that signals the two least plentiful
		// titles would otherwise be stranded into a group of three.
		group := n
		if n == 5 && counts[2] > counts[3] {
			group = 4
		}

		for i := 0; i < group; i++ {
			counts[i]--
		}
		cost += discounts[group]
	}

	return cost
}

